package bhw.bihrys.uuid.pet;
import bhw.bihrys.uuid.config.UuidConfig; import bhw.bihrys.uuid.player.PlayerDataManager; import bhw.bihrys.uuid.util.PermissionUtil; import net.minecraft.world.entity.TamableAnimal; import net.minecraft.world.item.Items; import net.minecraftforge.event.entity.player.PlayerInteractEvent; import net.minecraftforge.eventbus.api.SubscribeEvent; import net.minecraft.world.InteractionHand; import net.minecraft.world.InteractionResult; import net.minecraft.network.chat.Component;
public final class PetOwnerSwapHandler { @SubscribeEvent public static void interact(PlayerInteractEvent.EntityInteract e){ if(e.getLevel().isClientSide||!UuidConfig.INSTANCE.enablePetOwnerSwap||e.getHand()!=InteractionHand.MAIN_HAND||!e.getEntity().isCrouching()||!e.getEntity().getItemInHand(e.getHand()).is(Items.REDSTONE)||!(e.getTarget() instanceof TamableAnimal t)||!t.isTame()||!PermissionUtil.has((net.minecraft.server.level.ServerPlayer)e.getEntity(),UuidConfig.INSTANCE.petOwnerSwapPermissionLevel))return; var players=e.getEntity().getServer().getPlayerList().getPlayers(); if(!players.isEmpty()){t.setOwnerUUID(players.get(0).getUUID());e.getEntity().sendSystemMessage(Component.literal("已转移宠物主人"));e.setCancellationResult(InteractionResult.SUCCESS);e.setCanceled(true);} } }
